#!/usr/bin/env bash
#
# #5000 - `pm2 update` under the unit generated by `pm2 startup systemd`
# Needs sudo and systemd as PID 1 (GitHub ubuntu-latest host, not Docker)
#

cd "$(dirname "$0")/../.." || exit 1
ROOT=$PWD
PM2=$ROOT/bin/pm2
USER=${USER:-$(id -un)}
# own unit name: never touch the pm2-$USER unit of the machine
U=pm2-ci5000
UNIT_DIR=/etc/systemd/system
export PM2_HOME=/tmp/pm2ci/.pm2
mkdir -p /tmp/pm2ci

fail() {
  echo "######## FAIL: $*"
  sudo journalctl -u $U --no-pager | tail -40
  exit 1
}

# the process title is truncated to the length of the original command line
alive() { pgrep -f "God Daemon \(/tmp/pm2ci" >/dev/null; }

online() {
  $PM2 jlist 2>/dev/null | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try { console.log(JSON.parse(s).filter(p => p.pm2_env.status === "online").length) }
      catch (e) { console.log(0) }
    })'
}

wait_unit_down() {
  for _ in $(seq 60); do
    case $(systemctl show -p ActiveState --value $U) in inactive|failed) break;; esac
    sleep 0.5
  done
  sleep 2
}

reset() {
  sudo systemctl stop $U 2>/dev/null
  sudo rm -rf $UNIT_DIR/$U.service.d
  sudo systemctl daemon-reload
  $PM2 kill >/dev/null 2>&1
  pkill -f "God Daemon \(/tmp/pm2ci"
  rm -f $PM2_HOME/dump.pm2
  for n in a1 a2 a3; do $PM2 start "$ROOT/test/fixtures/child.js" -n $n >/dev/null; done
  $PM2 save >/dev/null
  $PM2 kill >/dev/null
}

# replace the ExecStop of the generated unit
exec_stop() {
  sudo mkdir -p $UNIT_DIR/$U.service.d
  printf '[Service]\nExecStop=\nExecStop=%s\n' "$1" | sudo tee $UNIT_DIR/$U.service.d/stop.conf >/dev/null
  sudo systemctl daemon-reload
}

# the stop command must reach pm2 and its guard (#5000)
guard_ran() {
  sudo journalctl -u $U --since "@$SINCE" --no-pager | grep -q "systemd stop command: $2" \
    || fail "$1: guard message missing"
}

update_keeps_apps() {
  sudo systemctl start $U || fail "$1: unit start"
  [ "$(online)" = 3 ] || fail "$1: apps not online after unit start"
  SINCE=$(date +%s)
  timeout 60 $PM2 update >/dev/null 2>&1 || fail "$1: pm2 update failed or hung"
  wait_unit_down
  alive || fail "$1: daemon killed by the unit stop command"
  [ "$(online)" = 3 ] || fail "$1: $(online)/3 apps online after pm2 update"
  echo "[V] $1"
}

operator_stop_kills() {
  sudo systemctl start $U || fail "$1: unit start"
  sudo systemctl stop $U
  sleep 1
  alive && fail "$1: daemon still running after systemctl stop"
  echo "[V] $1"
}

sudo env PATH="$PATH" $PM2 startup systemd -u "$USER" --hp /tmp/pm2ci --service-name $U >/dev/null || fail "pm2 startup"

reset
update_keeps_apps "pm2 update keeps the apps"
guard_ran "pm2 update keeps the apps"
reset
operator_stop_kills "systemctl stop kills the daemon"

# deterministic: the stop command runs once the new daemon is up
reset
exec_stop "/bin/sh -c 'sleep 4; exec $PM2 kill'"
update_keeps_apps "delayed ExecStop: pm2 update keeps the apps"
guard_ran "delayed ExecStop" "daemon not started by this service"

reset
sudo systemctl stop $U
sudo systemctl disable $U 2>/dev/null
sudo rm -rf $UNIT_DIR/$U.service $UNIT_DIR/$U.service.d
sudo systemctl daemon-reload
$PM2 kill >/dev/null 2>&1
echo "######## systemd tests OK"
